<div class="page-heading"><div><a class="back-link" href="<?= site_url('uttp') ?>">← Daftar UTTP</a><div class="eyebrow">Riwayat alat</div><h1><?= e($item->uttp_name.' · '.$item->brand) ?></h1><p><?= e($item->serial_number ?: 'Tanpa nomor seri') ?> · <?= e($item->service_address) ?></p></div></div><section class="card table-card"><div class="section-heading compact"><h2><?= (int)$pagination['total'] ?> riwayat permohonan</h2></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Permohonan</th><th>Tanggal</th><th>Layanan</th><th>Unit</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr><td><strong><?= e($row->request_no) ?></strong></td><td><?= e(tanggal_id($row->submitted_at)) ?></td><td><?= e(master_label('service_type',$row->service_type)) ?></td><td>#<?= (int)$row->unit_sequence ?></td><td><span class="badge <?= status_class($row->item_status) ?>"><?= e(status_label($row->item_status)) ?></span></td><td><a class="table-link" href="<?= site_url('permohonan/'.$row->request_id) ?>">Detail →</a></td></tr><?php endforeach; ?></tbody></table></div><?php if (!$rows): ?><div class="table-empty">UTTP ini belum pernah diajukan.</div><?php endif; ?><?= metro_pager($pagination,'uttp/riwayat/'.$item->id) ?></section>
